    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // fetch trades (response similar for REST & WS)
        //
        //   {
        //       "tradeId": "3263934920",
        //       "instId": "LTC-USDT",
        //       "price": "67.87",
        //       "size": "1",
        //       "side": "buy",
        //       "ts": "1707232020854"
        //   }
        //
        // my trades
        //   {
        //       "instId": "LTC-USDT",
        //       "tradeId": "1440847",
        //       "orderId": "2075705202",
        //       "fillPrice": "67.850000000000000000",
        //       "fillSize": "1.000000000000000000",
        //       "fillPnl": "0.000000000000000000",
        //       "side": "buy",
        //       "positionSide": "net",
        //       "fee": "0.040710000000000000",
        //       "ts": "1707224678878",
        //       "brokerId": ""
        //   }
        //
        // fetchMyTrades spot
        //     {
        //         "instId": "DOGE-USDT",
        //         "tradeId": "6000001623870",
        //         "orderId": "6000011777113",
        //         "fillPrice": "0.091480000000000000",
        //         "fillSize": "30.000000000000000000",
        //         "fillPnl": null,
        //         "side": "buy",
        //         "fee": "0.030000000000000000",
        //         "ts": "1775213753407",
        //         "brokerId": null,
        //         "feeCurrency": "base_currency"
        //     }
        //
        string? id = this.safeString(trade, "tradeId");
        string? marketId = this.safeString(trade, "instId");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, "-");
        string? symbol = ((string)(marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null));
        Int64? timestamp = this.safeInteger(trade, "ts");
        string? price = this.safeString2(trade, "price", "fillPrice");
        string? amount = this.safeString2(trade, "size", "fillSize");
        string? side = this.safeString(trade, "side");
        string? orderId = this.safeString(trade, "orderId");
        string? feeCost = this.safeString(trade, "fee");
        Dictionary<string, object> fee = null;
        string? feeCurrency = this.safeString(trade, "feeCurrency");
        bool isSpot = (feeCurrency != null);
        if ((feeCurrency == null))
        {
            feeCurrency = this.safeString(marketResolved, "settle");
        } else if (feeCurrency == "base_currency")
        {
            feeCurrency = this.safeString(marketResolved, "base");
        } else if (feeCurrency == "quote_currency")
        {
            feeCurrency = this.safeString(marketResolved, "quote");
        }
        if ((feeCost != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", feeCurrency },
            };
        }
        if (isSpot)
        {
            string? spotSymbol = ((string)add(add((marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("base") ? ((IDictionary<string, object>)marketResolved)["base"] : null), "/"), (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null)));
            double? cost = this.parseNumber(Precise.stringMul(price, amount));
            Dictionary<string, object> result = new Dictionary<string, object>() {
                { "info", trade },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
                { "symbol", spotSymbol },
                { "id", id },
                { "order", orderId },
                { "type", null },
                { "takerOrMaker", null },
                { "side", side },
                { "price", this.parseNumber(price) },
                { "amount", this.parseNumber(amount) },
                { "cost", cost },
                { "fee", new Dictionary<string, object>() {
                    { "cost", this.parseNumber(feeCost) },
                    { "currency", feeCurrency },
                } },
            };
            return ((Dictionary<string, object>)((object)(result)));
        } else
        {
            return this.safeTrade(new Dictionary<string, object>() {
                { "info", trade },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
                { "symbol", symbol },
                { "id", id },
                { "order", orderId },
                { "type", null },
                { "takerOrMaker", null },
                { "side", side },
                { "price", price },
                { "amount", amount },
                { "cost", null },
                { "fee", fee },
            }, marketResolved);
        }
    }

    /**
     * @method
     * @name blofin#fetchTrades
     * @description get the list of most recent trades for a particular symbol
     * @see https://blofin.com/docs#get-trades
     * @param {string} symbol unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum amount of trades to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.paginate] *only applies to publicGetMarketHistoryTrades* default false, when true will automatically paginate by calling this endpoint multiple times
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
     */
    public async override Task<List<ccxt.Trade>> FetchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        (bool?, object) paginateparamsPaginateVariable = this.handleOptionBoolAndParams(parameters, "fetchTrades", "paginate", false);
        bool? paginate = paginateparamsPaginateVariable.Item1;
        IDictionary<string, object> paramsPaginate = ((IDictionary<string, object>)paginateparamsPaginateVariable.Item2);
        if ((paginate == true))
        {
            return ccxt.BaseExchange.ToTradeList(await this.fetchPaginatedCallCursor("fetchTrades", symbol, since, limit, paramsPaginate, "tradeId", "after", null, 100));
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "instId", (market.ContainsKey("id") ? market["id"] : null) },
        };
        Dictionary<string, object> response = null;
        if ((limit != null))
        {
            request["limit"] = limit; // default 100
        }
        (string?, object) methodparamsMethodVariable = this.handleOptionStringAndParams(paramsPaginate, "fetchTrades", "method", "publicGetMarketTrades");
        string? method = methodparamsMethodVariable.Item1;
        IDictionary<string, object> paramsMethod = ((IDictionary<string, object>)methodparamsMethodVariable.Item2);
        if ((method == "publicGetMarketTrades"))
        {
            response = await this.publicGetMarketTrades(this.extend(request, paramsMethod));
        }
        List<object> data = this.safeList(response, "data", new List<object>() {});
        return ccxt.BaseExchange.ToTradeList(this.parseTrades(data, market, since, limit));
    }

    public override IList<object> parseOHLCV(object ohlcv, object market = null)
    {
        //
        //     [
        //         "1678928760000", // timestamp
        //         "24341.4", // open
        //         "24344", // high
        //         "24313.2", // low
        //         "24323", // close
        //         "628", // contract volume
        //         "2.5819", // base volume
        //         "62800", // quote volume
        //         "0" // candlestick state
        //     ]
        //
        return new List<object> {this.safeInteger(ohlcv, 0), this.safeNumber(ohlcv, 1), this.safeNumber(ohlcv, 2), this.safeNumber(ohlcv, 3), this.safeNumber(ohlcv, 4), this.safeNumber(ohlcv, 6)};
    }

    /**
     * @method
     * @name blofin#fetchOHLCV
     * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
     * @see https://blofin.com/docs#get-candlesticks
     * @param {string} symbol unified symbol of the market to fetch OHLCV data for
